const emailField = sheet.getField('联系邮箱');
if (Base.isFieldOfType(emailField, 'email')) {
  const success = await emailField.setValueAsync('rec123456', 'example@company.com');
  if (success) {
    console.log('邮箱更新成功');
  } else {
    console.log('邮箱更新失败');
  }
}

```

